"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[9391],{9391(e,s,i){i.d(s,{content:()=>l,description:()=>t,keywords:()=>a,title:()=>n});i(5043);var r=i(579);const n="Laboratoire Virtuel de Biologie : Dissections, Microscopie et Plus",t="Les laboratoires virtuels de biologie offrent une pratique illimit\xe9e de la dissection, des sp\xe9cimens parfaits pour la microscopie et l'accessibilit\xe9 pour tous les \xe9tudiants. D\xe9couvrez comment les travaux pratiques virtuels compl\xe8tent le travail en laboratoire r\xe9el.",a="laboratoire virtuel de biologie, dissection virtuelle, exp\xe9riences de biologie en ligne, simulation de microscopie, travaux pratiques de biologie, anatomie virtuelle",l=(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("p",{children:"Les professeurs de biologie font face \xe0 un ensemble unique de d\xe9fis que leurs coll\xe8gues de physique et de chimie ne rencontrent tout simplement pas. Quand vous enseignez le syst\xe8me circulatoire, vous ne pouvez pas simplement dessiner un diagramme au tableau et consid\xe9rer que c'est fait. Les \xe9l\xe8ves ont besoin de voir les structures, de comprendre les relations spatiales, et id\xe9alement de manipuler du vrai tissu. Mais c'est l\xe0 que les choses se compliquent."}),(0,r.jsx)("p",{children:"La grenouille que vous avez command\xe9e est arriv\xe9e d\xe9compos\xe9e. La moiti\xe9 de votre classe est trop d\xe9go\xfbt\xe9e pour la toucher de toute fa\xe7on. Vos lames de microscope sont ray\xe9es, les ampoules grillent constamment, et vous avez exactement 45 minutes pour aider 30 \xe9l\xe8ves \xe0 comprendre la structure du rein avant que la sonnerie retentisse. \xc7a vous dit quelque chose ?"}),(0,r.jsx)("p",{children:"Les laboratoires virtuels de biologie ne r\xe9solvent pas tous ces probl\xe8mes. Mais ils en adressent plus que vous ne pourriez l'imaginer."}),(0,r.jsx)("h2",{children:"Les Vrais D\xe9fis des Travaux Pratiques de Biologie"}),(0,r.jsx)("p",{children:"Soyons honn\xeates sur ce qui rend la biologie diff\xe9rente. La dimension \xe9thique seule cr\xe9e des complications que les autres mati\xe8res ne rencontrent pas."}),(0,r.jsxs)("p",{children:["La dissection animale reste p\xe9dagogiquement pr\xe9cieuse, mais elle est de plus en plus contest\xe9e. Les recherches montrent que les \xe9l\xe8ves qui ont des objections \xe9thiques \xe0 la dissection obtiennent souvent de moins bons r\xe9sultats aux \xe9valuations pratiques, non pas parce qu'ils sont moins capables, mais parce que leur malaise interf\xe8re avec l'apprentissage (",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s11191-020-00141-0",target:"_blank",rel:"noopener noreferrer",children:"Oakley, 2020"}),"). Quand un \xe9l\xe8ve se concentre sur le fait de ne pas \xeatre malade, il ne se concentre pas sur l'identification du cortex r\xe9nal."]}),(0,r.jsx)("p",{children:"Ensuite, il y a le co\xfbt. Un seul rein de porc pour dissection co\xfbte environ 3-5\u20ac chez les fournisseurs. Multipliez cela par 150 \xe9l\xe8ves par niveau, et vous regardez une allocation budg\xe9taire significative juste pour un sujet. Les c\u0153urs co\xfbtent plus cher. Les yeux sont \xe9tonnamment co\xfbteux. Et contrairement aux r\xe9actifs chimiques, les sp\xe9cimens biologiques ne peuvent \xeatre utilis\xe9s qu'une fois."}),(0,r.jsx)("p",{children:"Le temps aggrave ces probl\xe8mes. La vraie dissection prend du temps pour l'installation, du temps pour distribuer les sp\xe9cimens, du temps pour que les \xe9l\xe8ves travaillent sur la proc\xe9dure, et un temps significatif pour le nettoyage. Une le\xe7on de 50 minutes pourrait ne produire que 20 minutes de temps d'apprentissage r\xe9el. Si un \xe9l\xe8ve fait une erreur au d\xe9but de la dissection, il n'aura peut-\xeatre pas une autre chance d'essayer."}),(0,r.jsxs)("p",{children:["La microscopie pr\xe9sente ses propres frustrations. M\xeame un \xe9quipement bien entretenu n\xe9cessite des ajustements, et les \xe9l\xe8ves non familiers avec les techniques de mise au point peuvent passer la majeure partie d'une le\xe7on \xe0 chercher des sp\xe9cimens qui devraient \xeatre \xe9vidents. La recherche sur l'enseignement de la microscopie sugg\xe8re que les utilisateurs novices ont du mal avec la transition entre ce qu'ils voient \xe0 l'\u0153il nu et ce qui appara\xeet sous grossissement (",(0,r.jsx)("a",{href:"https://www.tandfonline.com/doi/full/10.1080/00219266.2013.837406",target:"_blank",rel:"noopener noreferrer",children:"Hug & McNeill, 2008"}),")."]}),(0,r.jsx)("h2",{children:"Ce Que les Laboratoires Virtuels de Biologie Offrent Vraiment"}),(0,r.jsx)("p",{children:"La dissection virtuelle n'est pas un gadget. Lorsqu'elle est correctement mise en \u0153uvre, elle r\xe9pond \xe0 plusieurs contraintes r\xe9elles qui limitent l'apprentissage dans les environnements traditionnels."}),(0,r.jsxs)("p",{children:["Le premier avantage est la r\xe9p\xe9tition. Dans une dissection physique, une fois que vous avez coup\xe9, vous ne pouvez pas d\xe9coup\xe9. Faites une incision au mauvais endroit et l'opportunit\xe9 d'apprentissage est perdue. La dissection virtuelle permet aux \xe9l\xe8ves de r\xe9p\xe9ter les proc\xe9dures autant de fois que n\xe9cessaire. La recherche sur l'acquisition des comp\xe9tences motrices d\xe9montre que la pratique r\xe9p\xe9t\xe9e avec r\xe9troaction est essentielle pour d\xe9velopper la comp\xe9tence proc\xe9durale (",(0,r.jsx)("a",{href:"https://journals.lww.com/acsm-msse/Fulltext/2012/11000/Cognitive_and_Physical_Demands_of_Virtual_Reality.28.aspx",target:"_blank",rel:"noopener noreferrer",children:"Gallagher et al., 2012"}),")."]}),(0,r.jsx)("p",{children:"Les laboratoires virtuels \xe9liminent \xe9galement enti\xe8rement les pr\xe9occupations \xe9thiques. Les \xe9l\xe8ves qui s'opposent \xe0 l'utilisation de sp\xe9cimens animaux peuvent quand m\xeame apprendre le m\xeame contenu anatomique. Il ne s'agit pas d'\xe9viter les conversations difficiles. Il s'agit de s'assurer que l'\xe9thique personnelle d'un \xe9l\xe8ve ne devienne pas un obstacle \xe0 son \xe9ducation scientifique."}),(0,r.jsx)("p",{children:"La capacit\xe9 de pause-et-examen compte plus que vous ne le pensez. Dans une vraie dissection, une fois que vous avez expos\xe9 une structure, vous devez agir rapidement avant que le tissu ne se d\xe9grade ou ne se dess\xe8che. Les sp\xe9cimens virtuels restent exactement comme ils sont, permettant aux \xe9l\xe8ves d'examiner les structures en d\xe9tail, de les comparer aux diagrammes des manuels, et de poser des questions sans pression."}),(0,r.jsx)("p",{children:"L'accessibilit\xe9 est peut-\xeatre l'avantage le plus sous-estim\xe9. Les \xe9l\xe8ves avec certains handicaps physiques peuvent avoir du mal avec le contr\xf4le moteur fin requis pour la dissection. Les \xe9l\xe8ves avec des sensibilit\xe9s sensorielles particuli\xe8res peuvent trouver les textures et les odeurs accablantes. Les alternatives virtuelles fournissent un acc\xe8s au m\xeame contenu \xe9ducatif sans ces obstacles."}),(0,r.jsx)("h2",{children:"Microscopie Virtuelle : L'Avantage Cach\xe9"}),(0,r.jsx)("p",{children:"Alors que la dissection virtuelle attire le plus d'attention, la microscopie virtuelle peut en fait offrir une valeur \xe9ducative plus constante."}),(0,r.jsx)("p",{children:"La microscopie physique d\xe9pend fortement de l'\xe9quipement. Un ensemble de microscopes pour la classe n\xe9cessite un entretien r\xe9gulier, le remplacement des ampoules et un stockage soigneux. M\xeame les microscopes bien entretenus produisent des r\xe9sultats variables, et les \xe9l\xe8ves passent un temps significatif \xe0 ajuster la mise au point plut\xf4t qu'\xe0 observer les sp\xe9cimens."}),(0,r.jsx)("p",{children:"La microscopie virtuelle fournit des sp\xe9cimens parfaits \xe0 chaque fois. Les \xe9l\xe8ves voient exactement ce qu'ils sont cens\xe9s voir, au grossissement appropri\xe9 \xe0 l'objectif d'apprentissage. Ils ne peuvent pas casser la lame, perdre la mise au point, ou ajuster la platine jusqu'\xe0 ce que le sp\xe9cimen tombe. Cela peut sembler de la triche, mais consid\xe9rez : l'objectif d'apprentissage est g\xe9n\xe9ralement d'identifier les structures, pas de d\xe9montrer la ma\xeetrise de l'\xe9quipement."}),(0,r.jsxs)("p",{children:["Les \xe9tudes comparant la microscopie virtuelle et physique dans les cours de biologie universitaires ont trouv\xe9 que les \xe9l\xe8ves utilisant des microscopes virtuels performaient aussi bien ou mieux sur les t\xe2ches d'identification, tout en passant moins de temps sur le d\xe9pannage technique (",(0,r.jsx)("a",{href:"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3762808/",target:"_blank",rel:"noopener noreferrer",children:"Heidger et al., 2002"}),"). La technologie g\xe8re la m\xe9canique, lib\xe9rant les \xe9l\xe8ves pour se concentrer sur la biologie."]}),(0,r.jsx)("h2",{children:"Cas d'Utilisation Sp\xe9cifiques Qui Fonctionnent"}),(0,r.jsx)("p",{children:"Tous les sujets de biologie ne b\xe9n\xe9ficient pas \xe9galement du traitement virtuel. Bas\xe9 sur notre travail avec les \xe9coles, certaines applications se d\xe9marquent."}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"La dissection du rein"})," se traduit exceptionnellement bien en format virtuel. Nous avons d\xe9j\xe0 \xe9crit sur ",(0,r.jsx)("a",{href:"/blog/virtual-kidney-dissection-send-engagement",children:"comment la dissection virtuelle du rein soutient les \xe9l\xe8ves SEND"}),", mais les avantages s'\xe9tendent \xe0 tous les apprenants. Les structures internes du rein, particuli\xe8rement les n\xe9phrons et les canaux collecteurs, sont difficiles \xe0 visualiser dans un sp\xe9cimen physique parce qu'elles sont microscopiques. La dissection virtuelle peut zoomer de l'organe entier au niveau cellulaire de mani\xe8re fluide, quelque chose d'impossible avec un vrai rein et un microscope d'\xe9l\xe8ve."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"La dissection du c\u0153ur"})," d\xe9montre des avantages similaires. Les sp\xe9cimens physiques de c\u0153ur de porcs ou de moutons fournissent de bonnes analogies pour l'anatomie humaine, mais couper \xe0 travers le muscle cardiaque r\xe9sistant n\xe9cessite des outils et une technique que les \xe9l\xe8ves n'ont souvent pas. Les versions virtuelles permettent aux \xe9l\xe8ves de faire des coupes nettes, d'examiner les structures des chambres sous plusieurs angles, et de tracer le flux sanguin \xe0 travers l'organe sans aucun risque de d\xe9truire le sp\xe9cimen avant de l'avoir compris."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"L'observation des cellules v\xe9g\xe9tales"})," b\xe9n\xe9ficie de la constance de la microscopie virtuelle. Pr\xe9parer des lames d'\xe9piderme d'oignon est une comp\xe9tence utile, mais c'est aussi minutieux et chronophage. Quand l'objectif d'apprentissage est \"identifier les structures des cellules v\xe9g\xe9tales\" plut\xf4t que \"pr\xe9parer une lame de microscope\", les sp\xe9cimens virtuels am\xe8nent les \xe9l\xe8ves au contenu \xe9ducatif plus rapidement."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Les cultures bact\xe9riennes"})," repr\xe9sentent un cas o\xf9 les alternatives virtuelles peuvent en fait \xeatre pr\xe9f\xe9rables. La vraie culture bact\xe9rienne implique des consid\xe9rations de bios\xe9curit\xe9, du temps d'incubation, et la possibilit\xe9 que la contamination ruine les r\xe9sultats. Les simulations de culture virtuelle peuvent montrer les mod\xe8les de croissance au fil du temps sans aucune de ces complications, et les \xe9l\xe8ves peuvent exp\xe9rimenter avec des variables (temp\xe9rature, nutriments, antibiotiques) de mani\xe8res qui seraient impraticables dans un laboratoire scolaire."]}),(0,r.jsx)("h2",{children:"Le Virtuel Remplace-t-il le Physique ? Non. Voici Pourquoi C'est la Mauvaise Question."}),(0,r.jsx)("p",{children:"Le d\xe9bat sur les travaux pratiques virtuels versus physiques suppose souvent que ce sont des options concurrentes. L'une gagnera, l'autre dispara\xeetra. Ce cadrage manque compl\xe8tement le point."}),(0,r.jsx)("p",{children:"La dissection physique offre des choses que le virtuel ne peut pas r\xe9pliquer. La texture du tissu, la r\xe9sistance en coupant \xe0 travers le muscle, l'odeur du conservateur : ce sont des parties de ce que signifie travailler avec du mat\xe9riel biologique. Pour les \xe9l\xe8ves envisageant des carri\xe8res en m\xe9decine, sciences v\xe9t\xe9rinaires ou travail de laboratoire, l'exp\xe9rience avec de vrais sp\xe9cimens compte."}),(0,r.jsxs)("p",{children:["Mais les travaux pratiques virtuels servent diff\xe9rents objectifs. Ils peuvent introduire des concepts avant un travail pratique physique, permettant aux \xe9l\xe8ves de comprendre ce qu'ils verront et feront avant de devoir le faire. La recherche sur la pr\xe9paration pr\xe9-laboratoire montre que les \xe9l\xe8ves qui pr\xe9visualisent les proc\xe9dures avant d'entrer au labo performent mieux et accomplissent les t\xe2ches plus efficacement (",(0,r.jsx)("a",{href:"https://pubs.acs.org/doi/10.1021/ed086p1330",target:"_blank",rel:"noopener noreferrer",children:"Johnstone & Al-Shuaili, 2001"}),")."]}),(0,r.jsx)("p",{children:"Les travaux pratiques virtuels peuvent \xe9galement \xe9tendre ce qui est possible apr\xe8s une session physique. Si les \xe9l\xe8ves n'ont qu'une chance de diss\xe9quer un rein en Troisi\xe8me, une version virtuelle leur permet de revisiter ce contenu pour la r\xe9vision. L'exp\xe9rience physique ancre l'apprentissage ; la version virtuelle le renforce."}),(0,r.jsx)("p",{children:"Pensez-y comme la simulation de conduite pour les apprentis conducteurs. Personne ne pr\xe9tend que les simulateurs devraient remplacer la vraie pratique de conduite. Mais tout le monde accepte que la simulation a un r\xf4le dans la pr\xe9paration, le d\xe9veloppement des comp\xe9tences, et la pratique de sc\xe9narios trop dangereux pour la vraie route."}),(0,r.jsx)("h2",{children:"Que Dit Vraiment la Recherche ?"}),(0,r.jsx)("p",{children:"Les preuves sur la dissection virtuelle ont consid\xe9rablement m\xfbri au cours de la derni\xe8re d\xe9cennie. Les premi\xe8res \xe9tudes comparaient souvent les r\xe9sultats utilisant des outils virtuels peu sophistiqu\xe9s contre des pratiques physiques bien \xe9tablies, favorisant sans surprise l'approche famili\xe8re. La recherche plus r\xe9cente utilisant des simulations modernes raconte une histoire diff\xe9rente."}),(0,r.jsxs)("p",{children:["Une m\xe9ta-analyse compl\xe8te de la dissection virtuelle versus physique n'a trouv\xe9 aucune diff\xe9rence significative dans les r\xe9sultats d'apprentissage lors de la mesure des connaissances anatomiques (",(0,r.jsx)("a",{href:"https://anatomypubs.onlinelibrary.wiley.com/doi/10.1002/ase.1626",target:"_blank",rel:"noopener noreferrer",children:"Lombardi et al., 2014"}),"). Les \xe9l\xe8ves ont appris le contenu aussi bien avec l'une ou l'autre m\xe9thode. L\xe0 o\xf9 des diff\xe9rences ont \xe9merg\xe9, elles concernaient les attitudes des \xe9l\xe8ves : certains \xe9l\xe8ves pr\xe9f\xe9raient le virtuel (souvent ceux avec des objections \xe9thiques \xe0 la dissection), tandis que d'autres pr\xe9f\xe9raient le physique (souvent ceux planifiant des carri\xe8res scientifiques)."]}),(0,r.jsxs)("p",{children:["Plus important encore, la recherche sugg\xe8re que combiner les approches produit de meilleurs r\xe9sultats que l'une ou l'autre seule. Une \xe9tude sur des \xe9tudiants en m\xe9decine a trouv\xe9 que ceux qui ont utilis\xe9 la dissection virtuelle comme pr\xe9paration pour le travail physique sur cadavre ont mieux perform\xe9 que les \xe9tudiants qui n'ont fait que de la dissection physique (",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s40037-014-0158-z",target:"_blank",rel:"noopener noreferrer",children:"Saltarelli et al., 2014"}),"). L'aper\xe7u virtuel les a aid\xe9s \xe0 comprendre ce qu'ils cherchaient avant de devoir le trouver dans un vrai sp\xe9cimen."]}),(0,r.jsx)("h2",{children:"Comment WhimsyLabs Aborde la Biologie"}),(0,r.jsx)("p",{children:"Nos simulations de biologie sont construites sur la m\xeame approche bas\xe9e sur la physique que nous utilisons pour la chimie et la physique. Cela peut sembler \xe9trange, puisque la biologie est moins \xe9videmment li\xe9e \xe0 la physique. Mais les organes sont des structures physiques. Les tissus ont des propri\xe9t\xe9s m\xe9caniques. Le sang coule selon la dynamique des fluides."}),(0,r.jsx)("p",{children:"Quand un \xe9l\xe8ve fait une incision dans notre rein virtuel, le tissu se s\xe9pare de mani\xe8re r\xe9aliste parce que nous avons mod\xe9lis\xe9 ses propri\xe9t\xe9s physiques. Quand ils tracent le chemin du sang \xe0 travers un c\u0153ur, le flux suit les gradients de pression qui entra\xeenent la vraie circulation. Ce n'est pas seulement du r\xe9alisme visuel ; c'est une pr\xe9cision comportementale qui soutient une compr\xe9hension authentique."}),(0,r.jsx)("p",{children:"Notre microscopie virtuelle s'int\xe8gre aux simulations de dissection, pour que les \xe9l\xe8ves puissent examiner le m\xeame rein au niveau de l'organe puis zoomer pour examiner la structure du n\xe9phron. La transition entre macro et micro aide les \xe9l\xe8ves \xe0 comprendre comment la fonction cellulaire produit des effets au niveau de l'organe."}),(0,r.jsx)("p",{children:"WhimsyCat, notre tuteur IA, fournit des conseils adapt\xe9s aux contextes de biologie. Quand un \xe9l\xe8ve a du mal \xe0 identifier le cortex et la m\xe9dulla, l'IA peut offrir des indices bas\xe9s sur des rep\xe8res visuels, des analogies avec d'autres structures qu'ils ont apprises, ou des questions qui les guident vers la r\xe9ponse. Le feedback est imm\xe9diat, quelque chose de difficile \xe0 accomplir quand vous circulez parmi 30 \xe9l\xe8ves avec des scalpels."}),(0,r.jsx)("h2",{children:"Pour Commencer"}),(0,r.jsx)("p",{children:"Si vous \xeates professeur de biologie curieux des travaux pratiques virtuels, la meilleure approche est d'en essayer un vous-m\xeame avant de l'utiliser avec des \xe9l\xe8ves. Voyez ce que \xe7a fait de faire une incision virtuelle. V\xe9rifiez si le d\xe9tail anatomique correspond \xe0 ce dont vous avez besoin pour votre programme. Demandez-vous : est-ce que cela aiderait mes \xe9l\xe8ves \xe0 mieux comprendre le contenu, ou serait-ce juste une nouveaut\xe9 ?"}),(0,r.jsx)("p",{children:"Nous offrons un acc\xe8s d\xe9mo \xe0 nos simulations de biologie sp\xe9cifiquement pour que les enseignants puissent les \xe9valuer correctement. Pas d'engagement, pas de pression commerciale. Juste vous, un rein virtuel, et la chance de d\xe9cider si cela pourrait fonctionner pour vos \xe9l\xe8ves."}),(0,r.jsxs)("p",{children:[(0,r.jsx)("a",{href:"/contact",children:"Demandez une d\xe9mo"})," et nous vous donnerons acc\xe8s \xe0 notre biblioth\xe8que compl\xe8te de simulations de biologie. Voyez par vous-m\xeame si la dissection virtuelle m\xe9rite une place dans votre bo\xeete \xe0 outils p\xe9dagogique."]}),(0,r.jsxs)("div",{className:"references-section",children:[(0,r.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,r.jsxs)("ul",{className:"references-list",children:[(0,r.jsxs)("li",{children:["Gallagher, A. G., Ritter, E. M., & Satava, R. M. (2012). Cognitive and psychomotor components of simulator-based training.",(0,r.jsx)("em",{children:" Medicine Meets Virtual Reality"}),", 20, 162-168.",(0,r.jsx)("a",{href:"https://journals.lww.com/acsm-msse/Fulltext/2012/11000/Cognitive_and_Physical_Demands_of_Virtual_Reality.28.aspx",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-1"),(0,r.jsxs)("li",{children:["Heidger, P. M., Dee, F., Consoer, D., Leaven, T., Duncan, J., & Kreiter, C. (2002). Integrated approach to teaching and testing in histology with real and virtual imaging.",(0,r.jsx)("em",{children:" The Anatomical Record"}),", 269(2), 107-112.",(0,r.jsx)("a",{href:"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3762808/",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-2"),(0,r.jsxs)("li",{children:["Hug, B., & McNeill, K. L. (2008). Use of first-hand and second-hand data in science.",(0,r.jsx)("em",{children:" Journal of Biological Education"}),", 42(4), 150-157.",(0,r.jsx)("a",{href:"https://www.tandfonline.com/doi/full/10.1080/00219266.2013.837406",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-3"),(0,r.jsxs)("li",{children:["Johnstone, A. H., & Al-Shuaili, A. (2001). Learning in the laboratory: Some thoughts from the literature.",(0,r.jsx)("em",{children:" University Chemistry Education"}),", 5(2), 42-51.",(0,r.jsx)("a",{href:"https://pubs.acs.org/doi/10.1021/ed086p1330",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-4"),(0,r.jsxs)("li",{children:["Lombardi, S. A., Hicks, R. E., Thompson, K. V., & Marbach-Ad, G. (2014). Are all hands-on activities equally effective?",(0,r.jsx)("em",{children:" Anatomical Sciences Education"}),", 7(6), 432-441.",(0,r.jsx)("a",{href:"https://anatomypubs.onlinelibrary.wiley.com/doi/10.1002/ase.1626",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-5"),(0,r.jsxs)("li",{children:["Oakley, J. (2020). Student attitudes toward virtual dissection: A review of the literature.",(0,r.jsx)("em",{children:" Science & Education"}),", 29, 891-910.",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s11191-020-00141-0",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-6"),(0,r.jsxs)("li",{children:["Saltarelli, A. J., Roseth, C. J., & Saltarelli, W. A. (2014). Human cadavers vs. multimedia simulation: A study of student learning in anatomy.",(0,r.jsx)("em",{children:" Perspectives on Medical Education"}),", 3(4), 287-300.",(0,r.jsx)("a",{href:"https://link.springer.com/article/10.1007/s40037-014-0158-z",target:"_blank",rel:"noopener noreferrer",children:" Link"})]},"ref-7")]})]}),(0,r.jsx)("h2",{children:"Lectures Compl\xe9mentaires"}),(0,r.jsxs)("ul",{children:[(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/virtual-kidney-dissection-send-engagement",children:"La Dissection Virtuelle du Rein Booste l'Engagement SEND"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/virtual-labs-vs-physical-labs-cost-benefit-analysis",children:"Labos Virtuels vs Physiques : Analyse Co\xfbt-B\xe9n\xe9fice"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/whimsycat-ai-tutor-transforming-science-education",children:"Rencontrez WhimsyCat : L'IA Qui Soutient, Ne Remplace Pas"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/blog/teachers-are-experts-custom-experiment-designer",children:"Les Enseignants Sont les Experts. Nous Construisons Juste les Outils."})})]})]})}}]);
